KummerDedekind.normalizedFactorsMapEquiv.code:
KummerDedekind.normalizedFactorsMapEquivNormalizedFactorsMinPolyMk.eq_1.{u_1, u_2} {R : Type u_1} {S : Type u_2}
  [CommRing R] [CommRing S] [Algebra R S] {x : S} {I : Ideal R} [IsDomain R] [IsIntegrallyClosed R] [IsDedekindDomain S]
  [NoZeroSMulDivisors R S] (hI : I.IsMaximal) (hI' : I ≠ ⊥) (hx : comap (algebraMap R S) (conductor R x) ⊔ I = ⊤)
  (hx' : _root_.IsIntegral R x) :
  normalizedFactorsMapEquivNormalizedFactorsMinPolyMk hI hI' hx hx' =
    let_fun this := ⋯;
    let f :=
      (quotAdjoinEquivQuotMap hx ⋯).symm.trans
        (((adjoin.powerBasis' hx').quotientEquivQuotientMinpolyMap I).toRingEquiv.trans (quotEquivOfEq ⋯));
    (normalizedFactorsEquivOfQuotEquiv f ⋯ ⋯).trans (normalizedFactorsEquivSpanNormalizedFactors ⋯).symm

WeakFEPair.f_modif.comment:
